const clean = (v) =>
  typeof v === "string" ? v.normalize("NFC").trim().replace(/\s+/g, " ") : "";

const cities = {
  "prishtinë": "Prishtinë",
  "prishtine": "Prishtinë",
  "prizren": "Prizren",
};

const cityKey = clean($json.city).toLowerCase();

const data = {
  customerName: clean($json.customerName),
  phone: clean($json.phone).replace(/[ ().-]/g, "").replace(/^00/, "+"),
  email: clean($json.email).toLowerCase(),
  city: cities[cityKey] || clean($json.city),
  pickup: clean($json.pickup),
  destination: clean($json.destination),
};

const errors = [];

if (Object.values(data).some((v) => !v))
  errors.push("Plotëso të gjitha fushat.");

if (data.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email))
  errors.push("Email-i nuk ka format të vlefshëm.");

if (data.phone && !/^\+[1-9]\d{7,14}$/.test(data.phone))
  errors.push("Shkruaj telefonin me prefiks ndërkombëtar, p.sh. +38344000001.");

if (data.city && !cities[cityKey])
  errors.push("Qyteti i zgjedhur nuk mbështetet.");

return {
  json: { ...$json, ...data, valid: errors.length === 0, errors },
};

const request = $('Normalizo dhe valido kërkesën').first().json;
const items = $input.all();
const records = items.map(item => item.json).filter(record => record.id);

let customerDecision = 'new';
let customerId = null;
let customerStatus = null;

if (records.length > 1) {
  customerDecision = 'conflict';
} else if (records.length === 1) {
  const record = records[0];
  const fields = record.fields ?? {};
  const email = String(fields.Email ?? '').trim().toLowerCase();
  const phone = String(fields['Numri i telefonit'] ?? '')
    .replace(/[\s().-]/g, '');

  if (email !== request.email || phone !== request.phone) {
    customerDecision = 'conflict';
  } else if (fields.Statusi === 'I bllokuar') {
    customerDecision = 'blocked';
  } else if (!['Aktiv', 'Guest'].includes(fields.Statusi)) {
    customerDecision = 'conflict';
  } else {
    customerDecision = 'existing';
    customerId = record.id;
    customerStatus = fields.Statusi;
  }
}

return [{
  json: {
    ...request,
    customerDecision,
    customerId,
    customerStatus,
    matchesFound: records.length
  },
  pairedItem: items.map((_, item) => ({ item }))
}];

