const candidates = $input.all()
  .filter(item => typeof item.json.id === 'string');

candidates.sort((a, b) =>
  a.json.id.localeCompare(b.json.id)
);

return candidates.slice(0, 1);

const crypto = require('crypto');

function createToken() {
  const token = crypto.randomBytes(32).toString('hex');
  const hash = crypto
    .createHash('sha256')
    .update(token)
    .digest('hex');

  return { token, hash };
}

return {
  json: {
    ...$json,
    actionTokens: {
      PRANO: createToken(),
      REFUZO: createToken()
    },
    expiresAt: new Date(
      Date.now() + 24 * 60 * 60 * 1000
    ).toISOString()
  }
};$input.item;
